#include <iostream>
#include <vector>
using namespace std;

int main() {
    unsigned long long n, a;
    cin >> n >> a;

    vector<int> b(n);
    for (long long i = static_cast<long long>(n) - 1; i >= 0; --i) {
        b[i] = a % 10;
        a /= 10;
    }

    unsigned long long count = 0;
    for (unsigned long long i = 0; i < n; ++i) {
        if (b[i] != 1)
            break;
        ++count;
    }

    if (count == n && count > 0)
        --count;

    cout << count + 1;
    return 0;
}

